        "11": {"title":"Travelling To The Grave","historicalNote":"From New Harp of Columbia. Title Index spells this 'Traveling to the Grave' (single L) - orthographic variant only, not flagged as a real discrepancy","firstLine":"Ye simple souls that stray Far from the paths","musicAttribution":{"credit":"Swan, W.H."}},
