        "14": {"title":"Mount Olivet","historicalNote":"From New Harp of Columbia. Title Index abbreviates this 'Mt. Olivet' - not flagged as a real discrepancy","firstLine":"Hark! how the choral song of heav'n Swells","musicAttribution":{"credit":"Swan, W.H."}},
