        "9": {"title":"The Converted Thief","firstLine":"As on the cross the Saviour hung","meter":"8.6.8.6 D","musicAttribution":{"credit":"More"}},
        "11": {"title":"Jerusalem","firstLine":"Jesus my all to heav'n is gone","meter":"8.8.8.8","musicAttribution":{"credit":"William Walker"}},
