        "14": {"title":"Minister's Farewell","firstLine":"Dear friends, farewell, I do you tell","meter":"8.6.8.6"},
        "15": {"title":"Davis","firstLine":"O Thou in whose presence my soul takes delight","meter":"11.8"},
        "16": {"title":"Star in the East","firstLine":"Hail the blest morn, see the great Mediator","meter":"10.11"},
        "18": {"title":"Complainer","firstLine":"I am a great complainer, that bears the name of Christ","meter":"7.6","musicAttribution":{"credit":"William Walker"}},
        "20": {"title":"The Family Bible","firstLine":"How painfully pleasing the fond recollection","meter":"12.11"},
        "28": {"title":"Tennessee","firstLine":"Afflictions, though they seem severe","meter":"8.6.8.6"},
        "29": {"title":"Solemn Thought","firstLine":"Remember, sinful youth, you must die","meter":"12.9.12.12.9","musicAttribution":{"credit":"F. Price"}},
        "30": {"title":"Separation","firstLine":"Our cheerful voices let us raise","meter":"8.6.8.6"},
        "32": {"title":"The Midnight Cry","firstLine":"When the midnight cry began","meter":"7.6.7.6.7.6.7.7"},
        "33": {"title":"Confidence","firstLine":"Though troubles assail, and dangers affright","meter":"10.10.11.11"},
        "36": {"title":"The Soldier's Return","firstLine":"Bright scenes of glory strike my sense","meter":"8.7"},
        "37": {"title":"The Christian Warfare","firstLine":"I find myself placed in a state of probation","meter":"12.11.11.11.12.11"},
        "38": {"title":"Resignation","firstLine":"My Shepherd will supply my need","meter":"8.6.8.6"},
        "41": {"title":"The Spiritual Sailor","firstLine":"The people called Christians","meter":"7.6","musicAttribution":{"credit":"I. Neighbours"}},
        "42": {"title":"Jefferson","firstLine":"Glorious things of thee are spoken","meter":"8.7"},
